from collections import deque


class ConnectGame:
    def __init__(self, board):
        self.cells = [line.strip().split() for line in board.strip().splitlines()]
        self.size = len(self.cells)

    def _neighbors(self, row, col):
        for drow, dcol in ((0, -1), (0, 1), (-1, 0), (-1, 1), (1, -1), (1, 0)):
            r, c = row + drow, col + dcol
            if 0 <= r < self.size and 0 <= c < self.size:
                yield r, c

    def _reaches(self, player, start_cols, goal_cols):
        seen = set()
        queue = deque(
            (r, c)
            for r in range(self.size)
            for c in start_cols
            if self.cells[r][c] == player
        )
        seen.update(queue)
        while queue:
            r, c = queue.popleft()
            if c in goal_cols:
                return True
            for nr, nc in self._neighbors(r, c):
                if (nr, nc) not in seen and self.cells[nr][nc] == player:
                    seen.add((nr, nc))
                    queue.append((nr, nc))
        return False

    def get_winner(self):
        if self._reaches("X", {0}, {self.size - 1}):
            return "X"
        if self._reaches("O", {0}, {self.size - 1}):
            return "O"
        return ""

